import { Highlight } from "@tiptap/extension-highlight";
import { Color, TextStyle } from "@tiptap/extension-text-style";

/**
 * 文字色与高亮色的预设色板。存进 HTML 的是色板名（`data-color="red"`），不是色值——
 * 色值由 `--rte-text-<名>` / `--rte-highlight-<名>` 令牌按亮/暗主题给出，换主题不必迁移数据，
 * 后端白名单也只需放行 `data-color` 一个属性。
 */
export const RICH_TEXT_PALETTE = [
  "gray",
  "red",
  "orange",
  "yellow",
  "green",
  "blue",
  "purple",
  "pink",
] as const;

export type RichTextPaletteColor = (typeof RICH_TEXT_PALETTE)[number];

export function isPaletteColor(value: unknown): value is RichTextPaletteColor {
  return typeof value === "string" && (RICH_TEXT_PALETTE as readonly string[]).includes(value);
}

/** 色板外的名字（手改的 HTML、旧数据、别处粘来的 `style="color:…"`）一律视为无色，不落进文档。 */
function parsePaletteAttribute(element: HTMLElement): RichTextPaletteColor | null {
  const name = element.getAttribute("data-color");
  return isPaletteColor(name) ? name : null;
}

function renderPaletteAttribute(attributes: Record<string, unknown>) {
  return isPaletteColor(attributes.color) ? { "data-color": attributes.color } : {};
}

/**
 * 只认带色板名的 `<span>`。原版 TextStyle 认的是带 `style` 的 span，外部粘来的
 * `style="color:…"` 会留下一层没有任何属性的空 `<span>`；这里色板外的 span 直接拆掉。
 */
export const PaletteTextStyle = TextStyle.extend({
  parseHTML() {
    return [
      {
        tag: "span",
        consuming: false,
        getAttrs: (element) => (isPaletteColor(element.getAttribute("data-color")) ? {} : false),
      },
    ];
  },
});

/** 沿用 Color 的 `setColor` / `unsetColor` 命令，只把渲染从 `style="color:…"` 换成 `data-color`。 */
export const PaletteColor = Color.extend({
  addGlobalAttributes() {
    return [
      {
        types: this.options.types,
        attributes: {
          color: {
            default: null,
            parseHTML: parsePaletteAttribute,
            renderHTML: renderPaletteAttribute,
          },
        },
      },
    ];
  },
});

/** 多色高亮；与 PaletteColor 同理只存色板名，`<mark>` 不带色时用主题的 `highlight` 令牌。 */
export const PaletteHighlight = Highlight.extend({
  addAttributes() {
    return {
      color: {
        default: null,
        parseHTML: parsePaletteAttribute,
        renderHTML: renderPaletteAttribute,
      },
    };
  },
}).configure({ multicolor: true });

import { Extension } from "@tiptap/core";
import { Plugin, PluginKey } from "@tiptap/pm/state";

const OFFICE_MARKER = /urn:schemas-microsoft-com|class="?Mso|mso-[a-z-]+\s*:|<o:p[\s>]/i;
const MSO_LIST = /mso-list\s*:\s*([^;"']+)/i;
const MSO_LIST_IGNORE = /mso-list\s*:\s*ignore/i;
/** Word 的列表标号：`1.` `a)` `(iv)` `IV.` 算有序，其余（`·` `§` `o` 及 Symbol 字体私有区字符）算无序。 */
const ORDERED_MARKER = /^\(?(\d+|[a-z]|[ivxlcdm]+)[.)]/i;
const DROPPED_ELEMENTS = "style, script, meta, link, title, xml";

/** 剪贴板 HTML 是否来自 Word / Outlook / OneNote 这类 Office 产品。 */
export function isOfficeHtml(html: string): boolean {
  return OFFICE_MARKER.test(html);
}

/**
 * 清洗 Office 粘贴的 HTML：`mso-list` 段落还原成真正的 `<ul>`/`<ol>`（含嵌套层级），去掉
 * `<o:p>`、书签锚点、条件注释、`mso-*` 样式与 `Mso*` 类名。非 Office 来源原样返回。
 *
 * 依赖 `DOMParser`，只在浏览器（或 jsdom）里调用——粘贴本来就只发生在客户端。
 */
export function cleanOfficeHtml(html: string): string {
  if (!isOfficeHtml(html)) return html;
  const doc = new DOMParser().parseFromString(html, "text/html");
  const body = doc.body;

  removeComments(body);
  for (const element of Array.from(body.querySelectorAll(DROPPED_ELEMENTS))) element.remove();
  convertLists(doc);
  for (const element of Array.from(body.querySelectorAll("*"))) cleanElement(element);

  return body.innerHTML.trim();
}

function removeComments(root: Node) {
  const walker = root.ownerDocument?.createTreeWalker(root, NodeFilter.SHOW_COMMENT);
  if (!walker) return;
  const comments: Node[] = [];
  while (walker.nextNode()) comments.push(walker.currentNode);
  for (const comment of comments) comment.parentNode?.removeChild(comment);
}

function unwrap(element: Element) {
  element.replaceWith(...Array.from(element.childNodes));
}

function cleanElement(element: Element) {
  if (!element.isConnected) return;
  const tag = element.tagName.toLowerCase();
  // 带命名空间的 Office 标签（o:p、w:sdt、v:shape…）：o:p 只是空段落占位，其余保留内容去掉壳。
  if (tag === "o:p") {
    element.remove();
    return;
  }
  if (tag.includes(":")) {
    unwrap(element);
    return;
  }
  // 书签与目录锚点（`<a name="_Toc…">`）没有 href，留着只会变成一段无意义的链接标记。
  if (tag === "a" && !element.hasAttribute("href")) {
    unwrap(element);
    return;
  }

  const style = element.getAttribute("style");
  if (style !== null) {
    const kept = style
      .split(";")
      .map((declaration) => declaration.trim())
      .filter((declaration) => declaration !== "" && !/^mso-/i.test(declaration));
    if (kept.length > 0) element.setAttribute("style", kept.join("; "));
    else element.removeAttribute("style");
  }

  const className = element.getAttribute("class");
  if (className !== null) {
    const kept = className.split(/\s+/).filter((name) => name !== "" && !/^mso/i.test(name));
    if (kept.length > 0) element.setAttribute("class", kept.join(" "));
    else element.removeAttribute("class");
  }
  element.removeAttribute("lang");

  if (tag === "span" && element.attributes.length === 0) unwrap(element);
}

interface ListParagraph {
  element: Element;
  level: number;
  ordered: boolean;
}

function readListParagraph(element: Element): ListParagraph | undefined {
  const match = MSO_LIST.exec(element.getAttribute("style") ?? "");
  // `mso-list: none` 出现在列表后接的续行段落上，它不是列表项。
  if (!match?.[1] || /ignore|none/i.test(match[1])) return undefined;
  const level = Number(/level(\d+)/i.exec(match[1])?.[1] ?? "1");

  const marker = Array.from(element.querySelectorAll("[style]")).find((candidate) =>
    MSO_LIST_IGNORE.test(candidate.getAttribute("style") ?? ""),
  );
  const markerText = (marker?.textContent ?? "").replace(/\s+/g, "");
  marker?.remove();

  return { element, level, ordered: ORDERED_MARKER.test(markerText) };
}

/** Word 不产出列表元素，而是一串带 `mso-list: l0 level2 lfo1` 的平级段落；连续的这类段落合成一棵列表。 */
function convertLists(doc: Document) {
  const paragraphs = Array.from(doc.body.querySelectorAll("p, h1, h2, h3, h4, h5, h6"))
    .map(readListParagraph)
    .filter((paragraph) => paragraph !== undefined);

  // 先按 DOM 相邻关系分组再动 DOM：建列表会把段落移走，之后就判断不了谁和谁挨着了。
  const runs: ListParagraph[][] = [];
  for (const paragraph of paragraphs) {
    const run = runs.at(-1);
    const last = run?.at(-1);
    if (run && last && last.element.nextElementSibling === paragraph.element) run.push(paragraph);
    else runs.push([paragraph]);
  }
  for (const run of runs) buildList(doc, run);
}

function buildList(doc: Document, run: ListParagraph[]) {
  const stack: { level: number; list: Element }[] = [];
  for (const { element, level, ordered } of run) {
    while (stack.length > 0 && (stack.at(-1)?.level ?? 0) > level) stack.pop();

    let top = stack.at(-1);
    if (!top || top.level < level) {
      const list = doc.createElement(ordered ? "ol" : "ul");
      const parentItem = top?.list.lastElementChild;
      if (top && parentItem) parentItem.appendChild(list);
      else if (top) top.list.appendChild(doc.createElement("li")).appendChild(list);
      else element.before(list);
      top = { level, list };
      stack.push(top);
    }

    const item = doc.createElement("li");
    const paragraph = doc.createElement("p");
    paragraph.append(...Array.from(element.childNodes));
    item.appendChild(paragraph);
    top.list.appendChild(item);
    element.remove();
  }
}

/** 把 {@link cleanOfficeHtml} 挂到 ProseMirror 的 `transformPastedHTML` 上。 */
export const OfficePaste = Extension.create({
  name: "officePaste",
  addProseMirrorPlugins() {
    return [
      new Plugin({
        key: new PluginKey("officePaste"),
        props: { transformPastedHTML: cleanOfficeHtml },
      }),
    ];
  },
});

import type { AnyExtension, Editor } from "@tiptap/core";
import { CodeBlockLowlight } from "@tiptap/extension-code-block-lowlight";
import { FileHandler } from "@tiptap/extension-file-handler";
import { Image } from "@tiptap/extension-image";
import { TaskItem, TaskList } from "@tiptap/extension-list";
import { TableKit } from "@tiptap/extension-table";
import { Placeholder } from "@tiptap/extensions";
import { Markdown } from "@tiptap/markdown";
import { StarterKit } from "@tiptap/starter-kit";
import bash from "highlight.js/lib/languages/bash";
import csharp from "highlight.js/lib/languages/csharp";
import css from "highlight.js/lib/languages/css";
import javascript from "highlight.js/lib/languages/javascript";
import json from "highlight.js/lib/languages/json";
import python from "highlight.js/lib/languages/python";
import sql from "highlight.js/lib/languages/sql";
import typescript from "highlight.js/lib/languages/typescript";
import xml from "highlight.js/lib/languages/xml";
import yaml from "highlight.js/lib/languages/yaml";
import { createLowlight } from "lowlight";
import { OfficePaste } from "./office-paste";
import { PaletteColor, PaletteHighlight, PaletteTextStyle } from "./palette";

/** 上传图片，resolve 成可直接放进 `<img src>` 的 URL。编辑器从不把图片转成 base64 内嵌。 */
export type UploadImage = (file: File) => Promise<string>;

export const IMAGE_MIME_TYPES = ["image/png", "image/jpeg", "image/gif", "image/webp"];

/**
 * 默认只注册后台业务常见的十来种语言，避免把 highlight.js 全量（约 190 种）打进包里。
 * 要更多语言就自己 `createLowlight()` + `register()` 后经 `lowlight` 选项传入。
 */
export const defaultLowlight = createLowlight({
  bash,
  csharp,
  css,
  javascript,
  json,
  python,
  sql,
  typescript,
  xml,
  yaml,
});

export interface RichTextExtensionOptions {
  /** 空文档时的占位文案；传函数可在不重建编辑器的前提下跟随语言切换。 */
  placeholder?: string | (() => string);
  /** 不给则粘贴/拖入图片被忽略、工具栏不出图片按钮。 */
  uploadImage?: UploadImage;
  onUploadError?: (error: unknown, file: File) => void;
  lowlight?: ReturnType<typeof createLowlight>;
  /** 追加到内置扩展之后，例如下游的 `@成员` / `#任务` Mention 节点。 */
  extensions?: AnyExtension[];
}

/** 上传完成时用户可能已经继续编辑，`pos` 只是首选位置，越界时落到文末。 */
export function insertUploadedImage(
  editor: Editor,
  file: File,
  upload: UploadImage,
  pos?: number,
  onError?: (error: unknown, file: File) => void,
): Promise<void> {
  return upload(file).then(
    (src) => {
      if (editor.isDestroyed) return;
      const image = { type: "image", attrs: { src, alt: file.name } };
      const at = pos === undefined ? undefined : Math.min(pos, editor.state.doc.content.size);
      if (at === undefined) editor.chain().focus().insertContent(image).run();
      else editor.chain().insertContentAt(at, image).run();
    },
    (error: unknown) => onError?.(error, file),
  );
}

/** 编辑器与只读展示共用的扩展清单——两边 schema 一致，同一份 HTML 才能原样往返。 */
export function createRichTextExtensions(options: RichTextExtensionOptions = {}): AnyExtension[] {
  const { placeholder, uploadImage, onUploadError, lowlight = defaultLowlight } = options;
  const extensions: AnyExtension[] = [
    StarterKit.configure({
      codeBlock: false,
      link: { openOnClick: false, autolink: true, defaultProtocol: "https" },
    }),
    TaskList,
    TaskItem.configure({ nested: true }),
    TableKit.configure({ table: { resizable: false } }),
    PaletteTextStyle,
    PaletteColor,
    PaletteHighlight,
    CodeBlockLowlight.configure({ lowlight }),
    Image.configure({ allowBase64: false }),
    Markdown,
    OfficePaste,
  ];

  if (placeholder !== undefined) {
    extensions.push(
      Placeholder.configure({
        placeholder: typeof placeholder === "function" ? () => placeholder() : placeholder,
      }),
    );
  }

  if (uploadImage) {
    extensions.push(
      FileHandler.configure({
        allowedMimeTypes: IMAGE_MIME_TYPES,
        onDrop: (editor, files, pos) => {
          for (const file of files)
            insertUploadedImage(editor, file, uploadImage, pos, onUploadError);
        },
        onPaste: (editor, files, pasteContent) => {
          // 同时带 HTML 的粘贴（网页、Word）交给常规 HTML 粘贴，否则同一张图会进来两份。
          if (pasteContent) return;
          for (const file of files)
            insertUploadedImage(editor, file, uploadImage, undefined, onUploadError);
        },
      }),
    );
  }

  return [...extensions, ...(options.extensions ?? [])];
}

import type { Editor } from "@tiptap/core";
import { useEditor } from "@tiptap/react";
import { useEffect, useRef, useState } from "react";
import { createRichTextExtensions, type RichTextExtensionOptions } from "./extensions";

export interface RichTextChange {
  /** 纯文本，块之间以换行分隔；供后端另存一份做搜索/摘要。 */
  text: string;
  editor: Editor;
}

export interface UseRichTextEditorOptions extends RichTextExtensionOptions {
  /** HTML 字符串；空文档对应 `""`。 */
  value: string;
  onChange?: (html: string, change: RichTextChange) => void;
  editable?: boolean;
  /** 透传到 contenteditable 根元素（id、aria-label、aria-invalid 等）。 */
  attributes?: Record<string, string>;
}

/** 空文档统一成 `""`：`<p></p>` 是 Tiptap 的空态表示，留着它表单的必填校验永远判不出空。 */
export function getEditorHtml(editor: Editor): string {
  return editor.isEmpty ? "" : editor.getHTML();
}

export function getMarkdown(editor: Editor): string {
  return editor.getMarkdown();
}

/** 用 Markdown 替换整篇内容。`emitUpdate` 为真时照常触发 onChange，存下来的仍是 HTML。 */
export function setMarkdown(editor: Editor, markdown: string, emitUpdate = true): void {
  editor.commands.setContent(markdown, { contentType: "markdown", emitUpdate });
}

/**
 * 受控的 Tiptap 编辑器：`value` 进、`onChange(html)` 出。
 *
 * 扩展清单只在挂载时读取一次（重建编辑器会丢光标与撤销栈），`extensions` 等选项变了不会生效；
 * `onChange` / `uploadImage` / `placeholder` 走 ref，换引用无需 memo。
 * SSR 下首帧返回 `null`（`immediatelyRender: false`），编辑器在水合后才创建，避免水合不一致。
 */
export function useRichTextEditor(options: UseRichTextEditorOptions): Editor | null {
  const { value, editable = true } = options;
  const latest = useRef(options);
  latest.current = options;
  // 记住最后一次「编辑器 → 外部」发出的值，外部把它原样传回时不 setContent，否则每次输入都重置光标。
  const lastEmitted = useRef(value);

  const [extensions] = useState(() =>
    createRichTextExtensions({
      ...options,
      placeholder:
        options.placeholder === undefined
          ? undefined
          : () => {
              const placeholder = latest.current.placeholder;
              return typeof placeholder === "function" ? placeholder() : (placeholder ?? "");
            },
      uploadImage:
        options.uploadImage &&
        ((file) =>
          latest.current.uploadImage?.(file) ?? Promise.reject(new Error("uploadImage removed"))),
      onUploadError: (error, file) => latest.current.onUploadError?.(error, file),
    }),
  );

  const editor = useEditor(
    {
      immediatelyRender: false,
      shouldRerenderOnTransaction: false,
      editable,
      content: value,
      extensions,
      editorProps: { attributes: options.attributes ?? {} },
      onUpdate: ({ editor: current }) => {
        const html = getEditorHtml(current);
        lastEmitted.current = html;
        latest.current.onChange?.(html, {
          text: current.getText({ blockSeparator: "\n" }),
          editor: current,
        });
      },
    },
    // 空依赖：编辑器只建一次。value / editable / attributes 的后续变化由下面的 effect 同步。
    [],
  );

  const attributesKey = JSON.stringify(options.attributes ?? {});
  useEffect(() => {
    if (!editor || editor.isDestroyed) return;
    editor.setOptions({
      editorProps: { ...editor.options.editorProps, attributes: JSON.parse(attributesKey) },
    });
  }, [editor, attributesKey]);

  useEffect(() => {
    if (!editor || editor.isDestroyed || value === lastEmitted.current) return;
    lastEmitted.current = value;
    editor.commands.setContent(value, { emitUpdate: false });
  }, [editor, value]);

  useEffect(() => {
    if (editor && !editor.isDestroyed && editor.isEditable !== editable) {
      editor.setEditable(editable, false);
    }
  }, [editor, editable]);

  return editor;
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import type { Editor } from "@tiptap/core";
import { useEditorState } from "@tiptap/react";
import {
  BoldIcon,
  CheckIcon,
  ChevronDownIcon,
  CodeIcon,
  ImagePlusIcon,
  ItalicIcon,
  LinkIcon,
  ListIcon,
  ListOrderedIcon,
  ListTodoIcon,
  MinusIcon,
  PaletteIcon,
  QuoteIcon,
  Redo2Icon,
  SquareCodeIcon,
  StrikethroughIcon,
  TableIcon,
  UnderlineIcon,
  Undo2Icon,
  UnlinkIcon,
} from "lucide-react";
import {
  type ComponentProps,
  type CSSProperties,
  Fragment,
  type ReactNode,
  useId,
  useRef,
  useState,
} from "react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Separator } from "@/components/ui/separator";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { IMAGE_MIME_TYPES, insertUploadedImage, type UploadImage } from "./extensions";
import { RICH_TEXT_PALETTE, type RichTextPaletteColor } from "./palette";

/** 工具栏按钮；`"|"` 是分组分隔线。顺序即渲染顺序。 */
export type RichTextToolbarItem =
  | "undo"
  | "redo"
  | "heading"
  | "bold"
  | "italic"
  | "underline"
  | "strike"
  | "code"
  | "color"
  | "bulletList"
  | "orderedList"
  | "taskList"
  | "blockquote"
  | "codeBlock"
  | "horizontalRule"
  | "link"
  | "image"
  | "table"
  | "|";

export const DEFAULT_TOOLBAR: RichTextToolbarItem[] = [
  "undo",
  "redo",
  "|",
  "heading",
  "|",
  "bold",
  "italic",
  "underline",
  "strike",
  "code",
  "color",
  "|",
  "bulletList",
  "orderedList",
  "taskList",
  "|",
  "blockquote",
  "codeBlock",
  "table",
  "horizontalRule",
  "|",
  "link",
  "image",
];

/** 选区气泡菜单的默认按钮：只放作用于选中文字的行内格式。 */
export const DEFAULT_BUBBLE_ITEMS: RichTextToolbarItem[] = [
  "bold",
  "italic",
  "underline",
  "strike",
  "code",
  "color",
  "link",
];

const HEADING_LEVELS = [1, 2, 3] as const;

function selectToolbarState({ editor }: { editor: Editor }) {
  return {
    canUndo: editor.can().undo(),
    canRedo: editor.can().redo(),
    heading: HEADING_LEVELS.find((level) => editor.isActive("heading", { level })) ?? 0,
    bold: editor.isActive("bold"),
    italic: editor.isActive("italic"),
    underline: editor.isActive("underline"),
    strike: editor.isActive("strike"),
    code: editor.isActive("code"),
    color: (editor.getAttributes("textStyle").color as RichTextPaletteColor | undefined) ?? null,
    highlight:
      (editor.getAttributes("highlight").color as RichTextPaletteColor | undefined) ?? null,
    highlighted: editor.isActive("highlight"),
    bulletList: editor.isActive("bulletList"),
    orderedList: editor.isActive("orderedList"),
    taskList: editor.isActive("taskList"),
    blockquote: editor.isActive("blockquote"),
    codeBlock: editor.isActive("codeBlock"),
    link: editor.isActive("link"),
    href: (editor.getAttributes("link").href as string | undefined) ?? "",
    inTable: editor.isActive("table"),
  };
}

type ToolbarState = ReturnType<typeof selectToolbarState>;

export interface RichTextToolbarProps extends Omit<ComponentProps<"div">, "children"> {
  editor: Editor;
  items?: RichTextToolbarItem[];
  uploadImage?: UploadImage;
  onUploadError?: (error: unknown, file: File) => void;
}

/** 编辑器工具栏，也被选区气泡菜单复用（换一组 `items`）。按钮的激活态订阅自编辑器状态。 */
export function RichTextToolbar({
  editor,
  items = DEFAULT_TOOLBAR,
  uploadImage,
  onUploadError,
  className,
  ...props
}: RichTextToolbarProps) {
  const L = useLocalization();
  const state = useEditorState({ editor, selector: selectToolbarState });
  const disabled = !editor.isEditable;
  const visible = items.filter((item) => item !== "image" || uploadImage);

  return (
    <div
      role="toolbar"
      aria-label={L("RichText:Toolbar")}
      className={cn("flex flex-wrap items-center gap-0.5", className)}
      {...props}
    >
      {visible.map((item, index) => {
        // 分隔线没有身份，用「前一个按钮名」作 key：配置里同一按钮不会出现两次。
        const key = item === "|" ? `|${visible[index - 1] ?? "start"}` : item;
        return (
          <Fragment key={key}>
            {item === "|" ? (
              <Separator orientation="vertical" className="mx-1 data-[orientation=vertical]:h-5" />
            ) : (
              <ToolbarControl
                item={item}
                editor={editor}
                state={state}
                disabled={disabled}
                uploadImage={uploadImage}
                onUploadError={onUploadError}
              />
            )}
          </Fragment>
        );
