/** 用户常省略协议直接贴 `example.com`；其余协议（含 javascript:）交给 Link 扩展的 isAllowedUri 拦截。 */
function normalizeHref(raw: string): string {
  const trimmed = raw.trim();
  if (trimmed === "" || /^[a-z][a-z\d+.-]*:/i.test(trimmed) || trimmed.startsWith("/")) {
    return trimmed;
  }
  return `https://${trimmed}`;
}

function LinkPopover({
  editor,
  state,
  disabled,
}: {
  editor: Editor;
  state: ToolbarState;
  disabled: boolean;
}) {
  const L = useLocalization();
  const inputId = useId();
  const [open, setOpen] = useState(false);
  const [href, setHref] = useState("");

  const apply = () => {
    const next = normalizeHref(href);
    const chain = editor.chain().focus().extendMarkRange("link");
    if (next === "") chain.unsetLink().run();
    else chain.setLink({ href: next }).run();
    setOpen(false);
  };

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next) setHref(state.href);
        setOpen(next);
      }}
    >
      <Tooltip>
        <TooltipTrigger asChild>
          <PopoverTrigger asChild>
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              disabled={disabled}
              aria-label={L("RichText:Link")}
              aria-pressed={state.link}
              onMouseDown={(event) => event.preventDefault()}
              className="aria-pressed:bg-accent aria-pressed:text-accent-foreground"
            >
              <LinkIcon />
            </Button>
          </PopoverTrigger>
        </TooltipTrigger>
        <TooltipContent>{L("RichText:Link")}</TooltipContent>
      </Tooltip>
      <PopoverContent align="start" className="w-80">
        <form
          className="flex items-center gap-2"
          onSubmit={(event) => {
            event.preventDefault();
            apply();
          }}
        >
          <label htmlFor={inputId} className="sr-only">
            {L("RichText:LinkUrl")}
          </label>
          <Input
            id={inputId}
            value={href}
            onChange={(event) => setHref(event.target.value)}
            placeholder="https://"
            inputMode="url"
            autoComplete="off"
          />
          <Button type="submit" size="sm">
            {L("RichText:LinkApply")}
          </Button>
          {state.link && (
            <Button
              type="button"
              variant="ghost"
              size="icon-sm"
              aria-label={L("RichText:LinkRemove")}
              onClick={() => {
                editor.chain().focus().extendMarkRange("link").unsetLink().run();
                setOpen(false);
              }}
            >
              <UnlinkIcon />
            </Button>
          )}
        </form>
      </PopoverContent>
    </Popover>
  );
}

